    /// <param name="onFinish">Callback to be called when the response is finished</param>
    /// <param name="options">Options including abort signal and client-defined tools</param>
    /// <returns>Response to send to the client or undefined</returns>
    abstract onChatMessage: _onFinish: obj * ?_options: OnChatMessageOptions -> JS.Promise<obj option>
    /// <summary>
    /// Called after a chat turn completes and the assistant message has been
    /// persisted. The turn lock is released before this hook runs, so it is
    /// safe to call <c>saveMessages</c> from inside.
    /// <br /><br />
    /// Fires for all turn completion paths: WebSocket chat requests,
    /// <c>saveMessages</c>, and auto-continuation.
    /// <br /><br />
    /// Responses triggered from inside <c>onChatResponse</c> (e.g. via <c>saveMessages</c>)
    /// do not fire <c>onChatResponse</c> recursively.
    /// <br /><br />
    /// The default implementation is a no-op.
    /// </summary>
    /// <param name="result">- Information about the completed turn</param>
    /// <example>
    /// <code>
    /// ```ts
    /// class MyAgent extends AIChatAgent&lt;Env&gt; {
    ///   protected async onChatResponse(result: ChatResponseResult) {
    ///     if (result.status === "completed") {
    ///       this.broadcast(JSON.stringify({ streaming: false }));
    ///     }
    ///   }
    /// }
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    abstract onChatResponse: _result: ChatResponseResult -> JS.Promise<unit> option
    /// <summary>
    /// Override this method to apply custom transformations to messages before
    /// they are persisted to storage. This hook runs <b>after</b> the built-in
    /// sanitization (OpenAI metadata stripping, Anthropic provider-executed tool
    /// payload truncation, empty reasoning part filtering).
    /// <br /><br />
    /// The default implementation returns the message unchanged.
    /// </summary>
    /// <param name="message">- The pre-sanitized message about to be persisted</param>
    /// <returns>The transformed message to persist</returns>
    /// <example>
    /// <code>
    /// ```ts
    /// class MyAgent extends AIChatAgent&lt;Env&gt; {
    ///   protected sanitizeMessageForPersistence(
    ///     message: UIMessage
    ///   ): UIMessage {
    ///     return {
    ///       ...message,
    ///       parts: message.parts.map(part =&gt; {
    ///         if ("output" in part &amp;&amp; typeof part.output === "string"
    ///             &amp;&amp; part.output.length &gt; 1000) {
    ///           return { ...part, output: "[redacted]" };
    ///         }
    ///         return part;
    ///       })
    ///     };
    ///   }
    /// }
    /// </code>
    /// <code>
    /// </code>
    /// </example>
    abstract sanitizeMessageForPersistence: message: obj -> obj
