    /// its reply inline rather than enqueuing (which would deadlock) or interleaving
    /// with a foreign turn.
    /// </summary>
    abstract _inSerializedDetachedDeliverySlot: obj with get, set
    /// <summary>
    /// Notification ids (<c>detached-finish:*</c> / <c>detached-ms:*</c>) currently being
