    /// </summary>
    abstract _registerAgentToolTurn: obj with get, set
    abstract startAgentToolRun: input: obj * options: AIChatAgent.StartAgentToolRun.Options -> JS.Promise<obj>
    abstract cancelAgentToolRun: runId: string * ?reason: obj -> JS.Promise<unit>
    /// <summary>
    /// Classify any in-flight chat-recovery on this child facet (#1630 / N6). A
