    /// <summary>
    /// Persist messages and trigger <c>onChatMessage()</c> for a new response.
    /// <br /><br />
    /// Waits for any active chat turn to finish before starting, so scheduled
    /// or programmatic messages never overlap an in-flight stream.
    /// <br /><br />
