    /// persisted <c>this.messages</c> when the turn actually starts. This avoids
    /// stale baselines when multiple <c>saveMessages()</c> calls queue up behind
    /// active work:
    /// <code lang="ts">
    /// await this.saveMessages((messages) =&gt; [...messages, syntheticMessage]);
    /// </code>
