/// <summary>
/// Extension of Agent with built-in chat capabilities
/// </summary>
/// <remarks>@template Env Environment type containing bindings</remarks>
type AIChatAgentConstructor =
    /// <summary>
    /// Default wait for trailing-edge debounced overlapping submits.
    /// </summary>
    abstract MESSAGE_DEBOUNCE_MS: obj with get, set
    abstract _mergeUserMessages: obj with get, set
    abstract _mergeMessageParts: obj with get, set
    abstract _cloneMessageParts: obj with get, set
    abstract _appendMergedText: obj with get, set
    abstract _progressSnapshotFromRow: obj with get, set
    abstract _stringifyAgentToolValue: obj with get, set
    abstract _parseAgentToolValue: obj with get, set
    abstract _extractLatestAssistantText: obj with get, set
    /// <summary>
    /// Context passed to <c>onChatRecovery</c> when an interrupted chat stream
    /// is detected after DO restart.
    /// </summary>
    abstract CHAT_FIBER_NAME: string
    /// <summary>
    /// Truncates large string values in <c>input</c> and <c>output</c> of tool parts that
    /// were executed server-side by the provider (e.g. Anthropic code_execution,
    /// text_editor). These payloads can be 200KB+ and are dead weight once the
    /// model has consumed the result.
    /// <br /><br />
    /// Anthropic web tools are excluded because their outputs are replayed on
    /// subsequent turns. Within other tool payloads, opaque encrypted fields are
    /// always preserved verbatim.
    /// </summary>
    abstract _truncateProviderExecutedToolPayloads: obj with get, set
    /// <summary>
    /// Recursively walks a value and truncates any string exceeding
    /// <c>PROVIDER_TOOL_MAX_STRING_LENGTH</c>, appending a size marker.
    /// <br /><br />
    /// The total output (content + marker) is kept within the threshold so
    /// re-running this function on already-truncated data is a no-op. Strings
    /// under opaque encrypted keys are preserved verbatim.
    /// </summary>
    abstract _truncateLargeStrings: obj with get, set
